import{z as n,x as s,o as l,c as p,q as r,j as B,D as E,d as t,s as o,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"淬灭剂负载","description":"","frontmatter":{"title":"淬灭剂负载","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/quencher-loading.md","filePath":"litho/quencher-loading.md","lastUpdated":1791063341000}'),d={name:"litho/quencher-loading.md"};function h(m,a,C,D,c,P){const i=s("Mermaid");return l(),p("div",null,[a[2]||(a[2]=r('<h1 id="淬灭剂负载" tabindex="-1">淬灭剂负载 <a class="header-anchor" href="#淬灭剂负载" aria-label="Permalink to &quot;淬灭剂负载&quot;">​</a></h1><div class="epigraph"><p>碱不是「有或没有」：负载决定打过阈值要多少酸、暗区还能收住多少漏酸，灵敏度与模糊在同一根浓度轴上对调。</p><footer>—— 据 Ito / Willson 化学放大思路，以及 Mack 对淬灭剂加载与阈值的表述整理</footer></div><p><a href="/litho/pag-quencher">上一课</a>把 PAG 与淬灭剂写成一对旋钮，并停在「有效酸 ≈ 生成酸 − 碱」。缺口是把碱这一侧展开成负载：浓度怎么走 \\(E_0\\)、暗区与后课才出场的酸程。酸放大器是额外增益，留给<a href="/litho/acid-amplifier">下一课</a>。PEB 温度仍不出场。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上一课已经说明阈值首先是化学的。产线改配方时，却很少只问「加不加碱」，而是问加多少。淬灭剂负载（loading）是膜里碱的摩尔浓度（或与 PAG 的摩尔比）。负载升高：必须生成更多酸才能打过中和，清场剂量 \\(E_0\\) 上移；暗区与 flare 产的那点酸被收得更干净；边沿争夺带变窄，后课扩散核等效缩短。负载太低：灵敏，但暗区起雾、环境胺一来顶部就被额外淬灭成 T-top。</p><p>缺口因此是浓度轴，不是再定义一次淬灭剂。把负载写成越大越好，会把扫描产能打穿；写成越小越好，会把暗区与延迟 PEB 稳定性交出去。</p><h3 id="摩尔比先于重量百分比" tabindex="-1">摩尔比先于重量百分比 <a class="header-anchor" href="#摩尔比先于重量百分比" aria-label="Permalink to &quot;摩尔比先于重量百分比&quot;">​</a></h3><p>换一种分子量更大的碱，同样 wt% 对应更少的分子数。签核用 PAG/淬灭剂摩尔比，或用「中和当量剂量」这种可测代理。193 nm 聚合物自身吸收不可算进产酸，负载实验必须固定光学栈，只改这一对。</p><p><span class="marginnote">数字实例：设碱 A 分子量 100、碱 B 分子量 250。同样配 1 wt%，B 的分子数只有 A 的 \\(100/250=0.4\\) 倍——重量百分比一样，「等着收酸的碱分子」却少了六成。这就是签核要用摩尔比而不是 wt% 的原因。</span></p><p><span class="marginnote">环境胺是额外的、从表面进来的淬灭，不是配方负载的一部分。提高配方内碱可以抗污染，却把 \\(E_0\\) 整根抬起来。上层涂层管表面胺，不代替本课的本体负载。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程上扫一条负载曲线：固定 PAG，变碱浓度，测 \\(E_0\\)、衬度、暗侵蚀、CD 与 LWR。通常看到：灵敏度变差、暗区变干净、iso–dense 与线端会动——因为阈值切点在空中像剖线上搬家。光可分解淬灭剂让亮区碱自己拆掉，负载的「暗区」与「亮区」不再同一浓度；本课只承认这种不对称，不写分子式。</p><p>与 PAG 联合：只加碱不加 PAG，酸图幅度不够，窗会先在密节距关上。只加 PAG 不加碱，增益高，漏酸。Ito 的放大解决光子少；负载解决放大之后暗区不能也亮——上一课的句子，本课变成一条可扫的轴。</p><p><span class="marginnote">直觉类比：碱负载像显影前预先撒进胶里的一把「收酸筹码」——撒得多，亮区得先攒够酸把筹码赢光才显影（\\(E_0\\) 上移、灵敏度变差），但暗区漏进来的那点杂酸（flare、环境胺）也一并被收走，底色更干净。撒得少则反之：灵敏，但暗区起雾。</span></p><h3 id="后课默认" tabindex="-1">后课默认 <a class="header-anchor" href="#后课默认" aria-label="Permalink to &quot;后课默认&quot;">​</a></h3><p>说到 CAR 配方，默认声明淬灭剂负载（或摩尔比），而不是只报「含碱」。酸程 \\(\\ell\\) 仍留给 PEB / 扩散课；本课只把负载记成缩短 \\(\\ell\\) 的化学库存，不给纳米数。</p>',16)),(l(),B(A,null,{default:E(()=>[o(i,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%B7%AC%E7%81%AD%E5%89%82%E8%B4%9F%E8%BD%BD%22%5D%20--%3E%20E0%5B%22E0%20%E4%B8%8A%E7%A7%BB%22%5D%0A%20%20Q%20--%3E%20DK%5B%22%E6%9A%97%E5%8C%BA%E4%B8%AD%E5%92%8C%22%5D%0A%20%20Q%20--%3E%20BAND%5B%22%E8%BE%B9%E6%B2%BF%E4%BA%89%E5%A4%BA%E5%B8%A6%E5%8F%98%E7%AA%84%22%5D%0A%20%20PAG%5B%22PAG%20%E4%BA%A7%E9%85%B8%22%5D%20--%3E%20NET%5B%22%E6%9C%89%E6%95%88%E9%85%B8%22%5D%0A%20%20Q%20--%3E%20NET%0A%20%20NET%20--%3E%20AA%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%3A%20%E9%85%B8%E6%94%BE%E5%A4%A7%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"曝光结束时酸浓度近似随剂量升。碱是预置的汇：浓度 \\(Q\\) 把「有效酸」的零点从 0 挪到 \\(Q\\)。空间上，亮区中心 \\(Q\\) 先被耗尽，催化全速；暗区酸永远低于 \\(Q\\)，脱保护接近零。边沿是 \\(Q\\) 与产酸梯度的交战，负载高则交战区更靠亮区一侧、更窄。Mack 把这写成阈值与衬度的化学来源；光学 \\(I_\\mathrm{th}\\) 只是把这条化学零点映射回强度。",-1)),a[5]||(a[5]=e("p",null,"负载也改环境窗口：表面胺消耗顶部的酸，等效局部加 \\(Q\\)。本体 \\(Q\\) 高，相对扰动小；本体 \\(Q\\) 低，T-top 先出现。这不是轨道事故的全部，但是配方能买的那一截裕量。",-1)),(l(),B(A,null,{default:E(()=>[o(i,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXP%5B%22%E6%9B%9D%E5%85%89%E7%94%9F%E6%88%90%E9%85%B8%22%5D%20--%3E%20CMP%7B%22%E4%B8%8E%E8%B4%9F%E8%BD%BD%20Q%20%E6%AF%94%E8%BE%83%22%7D%0A%20%20CMP%20--%3E%7C%22h%20%E8%BF%9C%E5%A4%A7%E4%BA%8E%20Q%22%7C%20BRIGHT%5B%22%E4%BA%AE%E5%8C%BA%EF%BC%9AQ%20%E8%80%97%E5%B0%BD%EF%BC%8C%E5%82%AC%E5%8C%96%E5%85%A8%E9%80%9F%22%5D%0A%20%20CMP%20--%3E%7C%22h%20%E7%BA%A6%E7%AD%89%E4%BA%8E%20Q%22%7C%20EDGE%5B%22%E8%BE%B9%E6%B2%BF%EF%BC%9A%E4%BA%89%E5%A4%BA%E5%B8%A6%EF%BC%8C%E9%9A%8F%E5%89%82%E9%87%8F%E7%A7%BB%E5%8A%A8%22%5D%0A%20%20CMP%20--%3E%7C%22h%20%E8%BF%9C%E5%B0%8F%E4%BA%8E%20Q%22%7C%20DARK%5B%22%E6%9A%97%E5%8C%BA%EF%BC%9A%E9%85%B8%E8%A2%AB%E6%94%B6%EF%BC%8C%E8%84%B1%E4%BF%9D%E6%8A%A4%E6%8E%A5%E8%BF%91%E9%9B%B6%22%5D%0A%20%20EDGE%20--%3E%20CD%5B%22CD%20%E5%88%87%E7%82%B9%20%2F%20%E9%98%88%E5%80%BC%E4%BD%8D%E7%BD%AE%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">常见误区：初学者容易以为阈值纯粹是光学量——「强度低于 \\(I_\\mathrm{th}\\) 就不显影」。实际上零点先由化学预置（负载 \\(Q\\)），光学只是把强度映射到这条化学阈值上；改负载就是搬零点，CD 切点会在空中像剖线上搬家，iso–dense 与线端跟着动。</span></p><p><span class="marginnote">EUV 上二次电子产酸，碱负载仍然是阈值，但事件稀疏，过高负载会把随机缺失推向更差的剂量。本课默认 DUV CAR；EUV 只警告不要把 ArF 负载表直接复印。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写某供应商的 wt% 表，不把 Ito 早期实验剂量当浸没工艺点。负胶 CAR 里碱仍在收酸，留下的是交联区，负载轴的方向相同、显影符号相反，不另开百科。酸放大器会在下一课把「生成酸」再乘一截，负载的零点还在，只是酸的来源变多，联合标定必须重做。</p><p>出气与镜头污染跟 PAG 挥发性更紧，跟无机碱负载不是同一卫生账。不要用加碱当抗出气处方。延迟 PEB 与环境胺实验是负载够不够的判据之一，不要只用灵敏度一张图签核——上一课已经要求过，本课把它绑在浓度轴上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>淬灭剂负载是浓度轴：抬 \\(E_0\\)、收暗区、收窄边沿争夺带。</li><li>用摩尔比或当量剂量签核，不要只报 wt%。</li><li>与 PAG 联合标定；碱不是越大越好。</li><li>环境胺是额外淬灭；本体负载只买相对裕量。</li><li>酸放大器是下一课的额外增益，不改「零点是碱」的定义。</li><li>延迟 PEB 与环境胺实验要和负载曲线一起签核。</li><li>出处：Ito &amp; Willson 化学放大；Mack, <em>Fundamental Principles of Optical Lithography</em>。</li></ul>',7))])}const f=n(d,[["render",h]]);export{_ as __pageData,f as default};
